begin;
insert into clinic_finance.accounts values ('5218','عمولات تسوية البطاقات','expense') on conflict do nothing;
create table clinic_finance.bank_statements(id uuid primary key default gen_random_uuid(),account text not null references clinic_finance.accounts(code),reference text not null,from_date date not null,to_date date not null,opening numeric(14,2) not null,closing numeric(14,2) not null,created_by uuid not null references public.admins(id),created_at timestamptz not null default now(),status text not null default 'pending' check(status in ('pending','approved')),reviewed_by uuid references public.admins(id),review_note text,unique(account,reference),check(to_date>=from_date));
create table clinic_finance.bank_rows(id uuid primary key default gen_random_uuid(),statement_id uuid not null references clinic_finance.bank_statements(id),row_no integer not null,day date not null,reference text not null,amount numeric(14,2) not null check(amount<>0),line_id uuid unique references clinic_finance.lines(id),unique(statement_id,row_no));
create table clinic_finance.pos_settlements(id uuid primary key default gen_random_uuid(),reference text not null unique,gross numeric(14,2) not null check(gross>0),fee numeric(14,2) not null check(fee>=0 and fee<gross),created_by uuid not null references public.admins(id),token uuid not null,payload jsonb not null,status text not null default 'pending' check(status in ('pending','approved','rejected')),reviewed_by uuid references public.admins(id),note text,created_at timestamptz not null default now(),unique(created_by,token));
create table clinic_finance.claim_followups(id uuid primary key default gen_random_uuid(),claim_id uuid not null references clinic_finance.insurance_claims(id),due_date date not null,batch text not null,note text not null,next_date date,created_by uuid not null references public.admins(id),created_at timestamptz not null default now());
create or replace function public.clinic_finance_bank_command(p_action text,p_payload jsonb,p_token uuid) returns uuid language plpgsql security definer set search_path=pg_catalog,public as $$
declare me uuid:=clinic_finance.require_access('create');v uuid;s clinic_finance.bank_statements%rowtype;r clinic_finance.pos_settlements%rowtype;j jsonb;n integer:=0;total numeric:=0;ln clinic_finance.lines%rowtype;br clinic_finance.bank_rows%rowtype;g numeric;f numeric;
begin perform clinic_finance.lock_day();
if coalesce(p_payload->>'opening','0') in ('NaN','Infinity','-Infinity') or coalesce(p_payload->>'closing','0') in ('NaN','Infinity','-Infinity') then raise exception 'المبالغ غير صالحة';end if;
if p_action='statement' then
 perform clinic_finance.require_access('review');if p_payload->>'account' not in ('1112','1114','1115') or length(trim(p_payload->>'reference'))<2 or jsonb_array_length(p_payload->'rows') not between 1 and 500 then raise exception 'بيانات كشف الحساب غير صالحة';end if;
 insert into clinic_finance.bank_statements(account,reference,from_date,to_date,opening,closing,created_by) values(p_payload->>'account',trim(p_payload->>'reference'),(p_payload->>'from')::date,(p_payload->>'to')::date,(p_payload->>'opening')::numeric,(p_payload->>'closing')::numeric,me) returning * into s;
 for j in select value from jsonb_array_elements(p_payload->'rows') loop n:=n+1;if (j->>'day')::date not between s.from_date and s.to_date or length(trim(j->>'reference'))<2 or j->>'amount' in ('NaN','Infinity','-Infinity') or (j->>'amount')::numeric<>round((j->>'amount')::numeric,2) then raise exception 'تاريخ أو مرجع أو قيمة سطر الكشف غير صالح';end if;insert into clinic_finance.bank_rows(statement_id,row_no,day,reference,amount) values(s.id,n,(j->>'day')::date,j->>'reference',(j->>'amount')::numeric);total:=total+(j->>'amount')::numeric;end loop;
 if s.opening+total<>s.closing then raise exception 'رصيد أول الكشف وحركاته لا يساوي رصيد آخر الكشف';end if;v:=s.id;
elsif p_action in ('match','unmatch','approve') then
 perform clinic_finance.require_access('review');select * into s from clinic_finance.bank_statements where id=(p_payload->>'statement_id')::uuid for update;if not found or s.status<>'pending' then raise exception 'الكشف غير متاح للمطابقة';end if;
 if p_action='approve' then if s.created_by=me then raise exception 'يلزم اعتماد شخص آخر';end if;if exists(select 1 from clinic_finance.bank_rows where statement_id=s.id and line_id is null) then raise exception 'توجد سطور كشف غير مطابقة';end if;if length(trim(p_payload->>'note'))<3 then raise exception 'اكتب نتيجة المراجعة';end if;update clinic_finance.bank_statements set status='approved',reviewed_by=me,review_note=p_payload->>'note' where id=s.id;
 else select * into br from clinic_finance.bank_rows where id=(p_payload->>'row_id')::uuid and statement_id=s.id for update;if not found then raise exception 'سطر الكشف غير موجود';end if;
 if p_action='match' then select * into ln from clinic_finance.lines where id=(p_payload->>'line_id')::uuid;if not found or ln.account<>s.account or ln.debit-ln.credit<>br.amount or exists(select 1 from clinic_finance.entries where id=ln.entry_id and business_date>s.to_date) then raise exception 'الحركة لا تطابق حساب وقيمة وتاريخ الكشف';end if;update clinic_finance.bank_rows set line_id=ln.id where id=br.id;else update clinic_finance.bank_rows set line_id=null where id=br.id;end if;end if;v:=s.id;
elsif p_action='pos_request' then
 select * into r from clinic_finance.pos_settlements where created_by=me and token=p_token;if found then if r.payload<>p_payload then raise exception 'مفتاح مستخدم لطلب آخر';end if;return r.id;end if;
 if length(trim(p_payload->>'reference'))<2 then raise exception 'مرجع التسوية مطلوب';end if;g:=(p_payload->>'gross')::numeric;f:=(p_payload->>'fee')::numeric;if g::text in ('NaN','Infinity','-Infinity') or f::text in ('NaN','Infinity','-Infinity') or g<>round(g,2) or f<>round(f,2) then raise exception 'المبالغ إلى قرشين';end if;
 insert into clinic_finance.pos_settlements(reference,gross,fee,created_by,token,payload) values(trim(p_payload->>'reference'),g,f,me,p_token,p_payload) returning id into v;
elsif p_action='pos_review' then
 perform clinic_finance.require_access('review');select * into r from clinic_finance.pos_settlements where id=(p_payload->>'id')::uuid for update;if not found or r.status<>'pending' or r.created_by=me or length(trim(p_payload->>'note'))<3 then raise exception 'يلزم طلب معلق ومراجع آخر وسبب القرار';end if;
 if (p_payload->>'approve')::boolean then select coalesce(sum(debit-credit),0) into g from clinic_finance.lines where account='1114';if r.gross>g then raise exception 'التسوية تتجاوز رصيد وسيط البطاقات';end if;perform clinic_finance.post('pos_net',r.id,'صافي تسوية بطاقات '||r.reference,null,'1112','1114',r.gross-r.fee);if r.fee>0 then perform clinic_finance.post('pos_fee',r.id,'عمولة بطاقات '||r.reference,null,'5218','1114',r.fee);end if;end if;
 update clinic_finance.pos_settlements set status=case when (p_payload->>'approve')::boolean then 'approved' else 'rejected' end,reviewed_by=me,note=p_payload->>'note' where id=r.id;v:=r.id;
elsif p_action='followup' then
 select id into v from clinic_finance.insurance_claims where id=(p_payload->>'claim_id')::uuid and (created_by=me or clinic_finance.allowed('review'));if v is null or length(trim(p_payload->>'note'))<3 or length(trim(p_payload->>'batch'))<2 then raise exception 'المطالبة أو بيانات المتابعة غير صالحة';end if;
 insert into clinic_finance.claim_followups(claim_id,due_date,batch,note,next_date,created_by) values(v,(p_payload->>'due_date')::date,trim(p_payload->>'batch'),trim(p_payload->>'note'),nullif(p_payload->>'next_date','')::date,me) returning id into v;
else raise exception 'إجراء غير معروف';end if;
insert into clinic_finance.audit(actor,action,entity_id) values(me,'bank_'||p_action,v);return v;end $$;
alter function public.clinic_finance_snapshot(date,date,integer) set schema clinic_finance;
alter function clinic_finance.clinic_finance_snapshot(date,date,integer) rename to bank_snapshot_base;
create function public.clinic_finance_snapshot(p_from date,p_to date,p_offset integer default 0) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$
declare v jsonb:=clinic_finance.bank_snapshot_base(p_from,p_to,p_offset);me uuid:=clinic_finance.require_access('view');reviewer boolean:=clinic_finance.allowed('review');begin
v:=v||jsonb_build_object('pos_settlements',(select coalesce(jsonb_agg(x),'[]') from(select * from clinic_finance.pos_settlements where reviewer or created_by=me order by created_at desc limit 200 offset p_offset)x),'claim_tracking',(select coalesce(jsonb_agg(x),'[]') from(select c.id,c.reference,c.insurer,clinic_finance.claim_due(c.id) due,coalesce(f.due_date,(c.created_at at time zone 'Africa/Cairo')::date) due_date,greatest(0,current_date-coalesce(f.due_date,(c.created_at at time zone 'Africa/Cairo')::date)) days_late,f.batch,f.note,f.next_date from clinic_finance.insurance_claims c left join lateral(select * from clinic_finance.claim_followups where claim_id=c.id order by created_at desc,id desc limit 1)f on true where (reviewer or c.created_by=me) and clinic_finance.claim_due(c.id)>0 order by due_date,c.id limit 200 offset p_offset)x));
if reviewer then v:=v||jsonb_build_object('bank_statements',(select coalesce(jsonb_agg(x),'[]') from(select s.*,(select count(*) from clinic_finance.bank_rows where statement_id=s.id and line_id is null) unmatched,(select coalesce(jsonb_agg(r order by row_no),'[]') from clinic_finance.bank_rows r where statement_id=s.id) rows from clinic_finance.bank_statements s order by created_at desc limit 200 offset p_offset)x),'bank_unmatched',(select coalesce(jsonb_agg(x),'[]') from(select l.id,l.account,l.debit-l.credit amount,e.business_date,e.description from clinic_finance.lines l join clinic_finance.entries e on e.id=l.entry_id where l.account in ('1112','1114','1115') and e.business_date<=p_to and not exists(select 1 from clinic_finance.bank_rows r where r.line_id=l.id) order by e.business_date desc,l.id limit 200 offset p_offset)x),'insurance_aging',(select coalesce(jsonb_agg(x),'[]') from(select insurer,case when days_late=0 then 'غير متأخر' when days_late<=30 then '1–30' when days_late<=60 then '31–60' when days_late<=90 then '61–90' else 'أكثر من 90' end bucket,sum(due) amount,count(*) claims from(select c.insurer,clinic_finance.claim_due(c.id) due,greatest(0,current_date-coalesce((select due_date from clinic_finance.claim_followups where claim_id=c.id order by created_at desc,id desc limit 1),(c.created_at at time zone 'Africa/Cairo')::date)) days_late from clinic_finance.insurance_claims c)z where due>0 group by insurer,bucket)x));end if;return v;end $$;
do $$ declare t text;begin foreach t in array array['bank_statements','bank_rows','pos_settlements','claim_followups'] loop execute format('alter table clinic_finance.%I enable row level security',t);end loop;end $$;
revoke all on all tables in schema clinic_finance from public,anon,authenticated;
revoke all on all functions in schema clinic_finance from public,anon,authenticated;
revoke all on function public.clinic_finance_bank_command(text,jsonb,uuid),public.clinic_finance_snapshot(date,date,integer) from public,anon;
grant execute on function public.clinic_finance_bank_command(text,jsonb,uuid),public.clinic_finance_snapshot(date,date,integer) to authenticated;
commit;
